// Fails with a transient error until the moment given in ?fail_until (unix ms), then succeeds.
// A retry re-runs this node with the same webhook input, so it sees the same fail_until:
// early retries fail, a later one passes. Deterministic "recovered" for demos and tests.
// Fire it with scripts/fire-recover.sh, which sets fail_until = now + 75 s.
const q = $('Webhook').first().json.query ?? {};
const until = Number(q.fail_until);

if (!Number.isFinite(until) || until <= 0) {
  throw new Error('chaos-recover needs ?fail_until=<unix ms>. Use scripts/fire-recover.sh');
}

const left = Math.ceil((until - Date.now()) / 1000);
if (left > 0) {
  throw new Error(`HTTP 503 Service unavailable (simulated outage, ${left} s left)`);
}

return [{ json: { ok: true, recovered_at: new Date().toISOString() } }];
